insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 12, 'E moveram os filhos de Israel por suas partidas do deserto de Sinai; e parou a nuvem no deserto de Parã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 13, 'E moveram a primeira vez ao dito do SENHOR por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 14, 'E a bandeira do acampamento dos filhos de Judá começou a marchar primeiro, por seus esquadrões: e Naassom, filho de Aminadabe, era sobre seu exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 15, 'E sobre o exército da tribo dos filhos de Issacar, Natanael filho de Zuar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 16, 'E sobre o exército da tribo dos filhos de Zebulom, Eliabe filho de Helom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 17, 'E depois que estava já desarmado o tabernáculo, moveram os filhos de Gérson e os filhos de Merari, que o levavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 18, 'Logo começou a marchar a bandeira do acampamento de Rúben por seus esquadrões: e Elizur, filho de Sedeur, era sobre seu exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 19, 'E sobre o exército da tribo dos filhos de Simeão, Selumiel filho de Zurisadai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 20, 'E sobre o exército da tribo dos filhos de Gade, Eliasafe filho de Deuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 21, 'Logo começaram a marchar os coatitas levando o santuário; e enquanto que eles traziam, os outros levantavam o tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 22, 'Depois começou a marchar a bandeira do acampamento dos filhos de Efraim por seus esquadrões: e Elisama, filho de Amiúde, era sobre seu exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 23, 'E sobre o exército da tribo dos filhos de Manassés, Gamaliel filho de Pedazur.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 24, 'E sobre o exército da tribo dos filhos de Benjamim, Abidã filho de Gideoni.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 25, 'Logo começou a marchar a bandeira do campo dos filhos de Dã por seus esquadrões, recolhendo todos os acampamentos: e Aiezer, filho de Amisadai, era sobre seu exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 26, 'E sobre o exército da tribo dos filhos de Aser, Pagiel filho de Ocrã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 27, 'E sobre o exército da tribo dos filhos de Naftali, Aira filho de Enã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 28, 'Estas são as partidas dos filhos de Israel por seus exércitos, quando se moviam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 29, 'Então disse Moisés a Hobabe, filho de Reuel midianita, seu sogro: Nós nos partimos para o lugar do qual o SENHOR disse: Eu a vós o darei. Vem conosco, e te faremos bem: porque o SENHOR falou bem a respeito de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 30, 'E ele lhe respondeu: Eu não irei, mas sim que me marcharei à minha terra e à minha parentela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 31, 'E ele lhe disse: Rogo-te que não nos deixes; porque tu conheces nossos alojamentos no deserto, e nos serás em lugar de olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 32, 'E será, que se vieres conosco, quando tivermos o bem que o SENHOR nos há de fazer, nós te faremos bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 33, 'Assim partiram do monte do SENHOR, caminho de três dias; e a arca da aliança do SENHOR foi diante deles caminho de três dias, buscando-lhes lugar de descanso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 34, 'E a nuvem do SENHOR ia sobre eles de dia, desde que partiram do acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 35, 'E foi, que em movendo a arca, Moisés dizia: Levanta-te, o SENHOR, e sejam dissipados teus inimigos, e fujam de tua presença os que te aborrecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 10, 36, 'E quando ela assentava, dizia: Volta, SENHOR, aos milhares de milhares de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 1, 'E aconteceu que o povo se queixou aos ouvidos do SENHOR: e ouviu-o o SENHOR, e ardeu seu furor, e acendeu-se neles fogo do SENHOR e consumiu a extremidade do acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 2, 'Então o povo clamou a Moisés, e Moisés orou ao SENHOR, e o fogo se apagou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 3, 'E chamou a aquele lugar Taberá; porque o fogo do SENHOR se acendeu neles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 4, 'E o povo misturado que havia no meio deles teve um intenso desejo; então os filhos de Israel voltaram-se, choraram, e disseram: Quem nos dera comer carne!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 5, 'Nós nos lembramos do peixe que comíamos no Egito de graça, dos pepinos, dos melões, dos alhos-porós, das cebolas, e dos alhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 6, 'mas agora a nossa alma se seca; nada há, a não ser maná, [diante dos] nossos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 7, 'O maná era como semente de coentro, e sua cor como cor de bdélio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 8, 'O povo se espalhava, e recolhia, e moía em moinhos, ou malhava em pilões, e o cozia em panelas, ou fazia dele bolos; e o seu sabor era como sabor de azeite fresco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 9, 'E quando o orvalho descia sobre o acampamento de noite, o maná descia sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 10, 'E Moisés ouviu o povo chorar por suas famílias, cada um à porta de sua tenda; e o furor do SENHOR se acendeu grandemente; também pareceu mal a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 11, 'E Moisés disse ao SENHOR: Por que fizeste mal a teu servo? E por que não achei favor aos teus olhos, que puseste sobremim a carga de todo este povo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 12, 'Por acaso fui eu que concebi todo este povo? Fui o que o dei à luz, para que me digas: Leva-o em teu colo, como uma ama leva um bebê de peito, à terra da qual juraste a seus pais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 13, 'De onde eu teria carne para dar a todo este povo? Porque choram a mim, dizendo: Dá-nos carne para comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 14, 'Não posso suportar sozinho todo este povo, porque é pesado demais para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 15, 'E se assim fazes tu comigo, eu te rogo que me mates, se achei favor aos teus olhos; e que não me deixes ver a minha calamidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 16, 'Então o SENHOR disse a Moisés: Ajunta-me setenta homens dos anciãos de Israel, de quem sabes que são anciãos do povo, e seus oficiais; e traze-os à porta do tabernáculo do testemunho, e esperem ali contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 17, 'E eu descerei e falarei ali contigo; e tomarei do espírito que está sobre ti, e [o] porei neles; e contigo levarão a carga do povo, para que tu não [a] leves sozinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 18, 'Porém dirás ao povo: Santificai-vos para amanhã, e comereis carne; porque chorastes em ouvidos do SENHOR, dizendo: Quem nos dera comer carne! Certamente estávamos bem no Egito! O SENHOR, pois, vos dará carne, e comereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 19, 'Não comereis um dia, nem dois dias, nem cinco dias, nem dez dias, nem vinte dias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 20, 'mas sim, um mês inteiro, até que vos saia pelas narinas, e sintais repulsa dela, porque rejeitastes o SENHOR que está no meio de vós, e chorastes diante dele, dizendo: Para que saímos do Egito?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 21, 'Então disse Moisés: Seiscentos mil a pé é este povo no meio do qual estou; e tu dizes: Eu lhes darei carne, e comerão um mês inteiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 22, 'Por acaso serão degoladas para eles ovelhas e bois que lhes bastem? Ou se ajuntarão para eles todos os peixes do mar para que lhes sejam suficientes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 23, 'Porém o SENHOR respondeu a Moisés: Por acaso o poder do SENHOR é curto? Agora verás se a minha palavra te acontecerá ou não.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 24, 'E Moisés saiu, e disse ao povo as palavras do SENHOR; e ajuntou setenta homens dos anciãos do povo, e os pôs ao redor da tenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 25, 'Então o SENHOR desceu na nuvem, e lhe falou; e tomou do espírito que estava sobre ele, e o pôs sobre aqueles setenta anciãos; e aconteceu que, quando o espírito repousou sobre eles, profetizaram, mas depois nunca mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 26, 'Porém ficaram no acampamento dois homens, um chamado Eldade e o outro Medade, sobre os quais o espírito também repousou (porque estavam entre os inscritos, mas não haviam saído à tenda); e profetizaram no acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 27, 'Então um jovem correu, e avisou a Moisés, e disse: Eldade e Medade estão profetizando no acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 28, 'Então Josué, filho de Num, assistente de Moisés desde a sua juventude, respondeu, e disse: Meu senhor Moisés, impede-os.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 29, 'E Moisés lhe respondeu: Tens tu ciúmes por mim? Bom seria se todos do povo do SENHOR fossem profetas, que o SENHOR pusesse seu Espírito sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 30, 'E Moisés recolheu-se ao acampamento, ele e os anciãos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 31, 'E saiu um vento do SENHOR, que trouxe codornizes do mar, e deixou-as sobre o acampamento, de um dia de caminho de um lado e do outro, ao redor do acampamento, e quase dois côvados sobre a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 32, 'Então o povo se levantou e recolheu para si codornizes durante todo aquele dia, e toda a noite, e todo o dia seguinte.O que recolheu menos recolheu dez ômeres; e as estenderam para si ao redor do acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 33, 'A carne ainda estava entre os dentes deles, antes que fosse mastigada, quando o furor do SENHOR se acendeu no povo, e o SENHOR feriu o povo com uma praga muito grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 34, 'Por isso aquele lugar recebeu o nome de Quibrote-Hataavá, porque ali sepultaram o povo que teve o desejo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 11, 35, 'De Quibrote-Hataavá o povo partiu para Hazerote, e ficaram em Hazerote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 1, 'E Miriã e Arão falaram contra Moisés por causa da mulher cuxita que havia tomado; porque ele havia tomado uma cuxita por esposa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 2, 'E disseram: Por acaso o SENHOR falou somente por Moisés? Não falou também por nós? E o SENHOR ouviu isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 3, 'Aquele homem Moisés era muito manso, mais que todos os homens que havia sobre a terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 4, 'E logo disse o SENHOR a Moisés, a Arão, e a Miriã: Saí vós três à tenda do encontro. E saíram eles três.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 5, 'Então o SENHOR desceu na coluna da nuvem, e pôs-se à entrada da tenda, e chamou a Arão e a Miriã; e saíram eles ambos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 6, 'E ele lhes disse: Ouvi agora minhas palavras: se tiverdes profeta do SENHOR, lhe aparecerei em visão, em sonhos falarei com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 7, 'Não assim a meu servo Moisés, que é fiel em toda minha casa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 8, 'Face a face falarei com ele, e às claras, e não por figuras; e verá a aparência do SENHOR: por que pois não tivestes temor de falar contra meu servo Moisés?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 9, 'Então o furor do SENHOR se acendeu neles; e ele se foi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 10, 'E a nuvem se afastou da tenda; e eis que Miriã era leprosa como a neve; e Arão olhou para Miriã, e eis que estava leprosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 11, 'E disse Arão a Moisés: Ah! Senhor meu, não ponhas sobre nós este pecado; porque loucamente o fizemos, e pecamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 12, 'Rogo que ela não seja como um que sai morto do ventre de sua mãe, com a metade de sua carne já consumida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 13, 'Então Moisés clamou ao SENHOR, dizendo: Rogo-te, ó Deus, que a sares agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 14, 'Respondeu o SENHOR a Moisés: Se o seu pai houvesse cuspido em sua face, não seria envergonhada por sete dias? Que ela esteja fora do acampamento durante sete dias, e depois seja trazida de volta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 15, 'Assim Miriã foi expulsa do acampamento por sete dias; e o povo não partiu até que Miriã voltasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 12, 16, 'Depois o povo partiu de Hazerote, e assentaram o acampamento no deserto de Parã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 1, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 2, '“Envia homens que reconheçam a terra de Canaã, a qual eu dou aos filhos de Israel; de cada tribo de seus pais enviareis um homem, cada um líder entre eles.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 3, 'E Moisés os enviou desde o deserto de Parã, conforme a palavra do SENHOR; e todos aqueles homens eram líderes dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 4, 'Os nomes dos quais são estes: da tribo de Rúben, Samua, filho de Zacur.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 5, 'Da tribo de Simeão, Safate, filho de Hori.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 6, 'Da tribo de Judá, Calebe, filho de Jefoné.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 7, 'Da tribo de Issacar, Jigeal, filho de José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 8, 'Da tribo de Efraim, Oseias, filho de Num.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 9, 'Da tribo de Benjamim, Palti, filho de Rafu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 10, 'Da tribo de Zebulom, Gadiel, filho de Sodi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 11, 'Da tribo de José: pela tribo de Manassés, Gadi, filho de Susi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 12, 'Da tribo de Dã, Amiel, filho de Gemali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 13, 'Da tribo de Aser, Setur, filho de Micael.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 14, 'Da tribo de Naftali, Nabi, filho de Vofsi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 15, 'Da tribo de Gade, Guel, filho de Maqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 16, 'Estes são os nomes dos homens que Moisés enviou para reconhecer a terra; e a Oseias, filho de Num, Moisés lhe pôs o nome de Josué.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 17, 'Então Moisés os enviou para reconhecer a terra de Canaã, dizendo-lhes: “Subi por aqui, pelo sul, e subi ao monte:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 18, 'e observai a terra que tal é; e o povo que a habita, se é forte ou débil, se pouco ou numeroso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 19, 'qual é a terra habitada, se é boa ou má; e quais são as cidades habitadas, se de tendas ou de fortalezas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 20, 'e qual é o terreno, se é fértil ou fraco, se nele há ou não árvores; esforçai-vos, e colhei do fruto daquela terra.” E o tempo era o tempo das primeiras uvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 21, 'E eles subiram, e reconheceram a terra desde o deserto de Zim até Reobe, entrando em Hamate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 22, 'E subiram pelo sul, e vieram até Hebrom: e ali estavam Aimã, e Sesai, e Talmai, filhos de Anaque. Hebrom foi edificada sete anos antes de Zoã, a do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 23, 'E chegaram até o ribeiro de Escol, e dali cortaram um ramo com um cacho de uvas, o qual trouxeram dois em uma vara, e das romãs e dos figos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 24, 'E chamou-se aquele lugar vale de Escol pelo cacho que cortaram dali os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 25, 'E voltaram de reconhecer a terra ao fim de quarenta dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 26, 'E andaram e vieram a Moisés e a Arão, e a toda a congregação dos filhos de Israel, no deserto de Parã, em Cades, e deram-lhes a resposta, e a toda a congregação, e lhes mostraram o fruto da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 27, 'E lhe contaram, e disseram: Nós chegamos à terra à qual nos enviaste, a que certamente flui leite e mel; e este é o fruto dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 28, 'Mas o povo que habita aquela terra é forte, e as cidades muito grandes e fortes; e também vimos ali os filhos de Anaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 29, 'Amaleque habita a terra do sul; e os heteus, e os jebuseus, e os amorreus, habitam no monte; e os cananeus habitam junto ao mar, e à beira do Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 30, 'Então Calebe fez calar o povo diante de Moisés, e disse: Subamos logo, e passemos a ela; que mais poderemos que ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 31, 'Mas os homens que subiram com ele, disseram: Não poderemos subir contra aquele povo; porque é mais forte que nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 32, 'E falaram mal entre os filhos de Israel da terra que haviam reconhecido, dizendo: A terra por de onde passamos para reconhecê-la, é terra que consome a seus moradores; e todo o povo que vimos em meio dela, são homens de grande estatura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 13, 33, 'Também vimos ali gigantes, filhos de Anaque, raça dos gigantes: e éramos nós, à nossa aparência, como gafanhotos; e assim lhes parecíamos a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 1, 'Então toda a congregação levantaram grito, e deram vozes: e o povo chorou aquela noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 2, 'E queixaram-se contra Moisés e contra Arão todos os filhos de Israel; e disse-lhes toda a multidão: Melhor seria se tivéssemos morrido na terra do Egito; ou melhor seria se tivéssemos morrido neste deserto!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 3, 'E por que nos traze o SENHOR a esta terra para cair à espada e que nossas mulheres e nossos meninos sejam por presa? não nos seria melhor voltarmos ao Egito?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 4, 'E diziam um ao outro: Façamos um capitão, e voltemos ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 5, 'Então Moisés e Arão caíram sobre seus rostos diante de toda a multidão da congregação dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 6, 'E Josué filho de Num, e Calebe filho de Jefoné, que eram dos que haviam reconhecido a terra, rasgaram suas roupas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 7, 'E falaram a toda a congregação dos filhos de Israel, dizendo: A terra por de onde passamos para reconhecê-la, é terra em grande maneira boa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 8, 'Se o SENHOR se agradar de nós, ele nos porá nesta terra, e a entregará a nós; terra que flui leite e mel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 9, 'Portanto, não sejais rebeldes contra o SENHOR, nem temais ao povo desta terra, porque nosso pão são: seu amparo se afastou deles, e conosco está o SENHOR: não os temais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 10, 'Então toda a multidão falou de apedrejá-los com pedras. Mas a glória do SENHOR se mostrou no tabernáculo do testemunho a todos os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 11, 'E o SENHOR disse a Moisés: Até quando me há de irritar este povo? até quando não me há de crer com todos os sinais que fiz em meio deles?.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 12, 'Eu lhe ferirei de mortandade, e o destruirei, e a ti te porei sobre gente grande e mais forte que eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 13, 'E Moisés respondeu ao SENHOR: Logo os egípcios o ouvirão, porque do meio deles tiraste a este povo com tua força:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 14, 'E o dirão aos habitantes desta terra; os quais ouviram que tu, ó SENHOR, estavas em meio deste povo, que olho a olho aparecias tu, ó SENHOR, e que tua nuvem estava sobre eles, e que de dia ias diante deles em coluna de nuvem, e de noite em coluna de fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 15, 'E que fizeste morrer a este povo como a um homem: e as nações que houverem ouvido tua fama falarão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 16, 'Porque não pôde o SENHOR meter este povo na terra da qual lhes havia jurado, os matou no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 17, 'Agora, pois, eu te rogo que seja engrandecida a força do Senhor, como o falaste, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 18, 'O SENHOR, tardio de ira e grande em misericórdia, que perdoa a iniquidade e a rebelião, e deixa impune o culpado; que visita a maldade dos pais sobre os filhos até a terceira geração e até a quarta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 19, 'Perdoa agora a iniquidade deste povo segundo a grandeza de tua misericórdia, e como perdoaste a este povo desde Egito até aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 20, 'Então o SENHOR disse: Eu o perdoei conforme tu dito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 21, 'Mas, certamente vivo eu e minha glória inche toda a terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 22, 'Que todos os que viram minha glória e meus sinais que fiz no Egito e no deserto, e me tentaram já dez vezes, e não ouviram minha voz,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 23, 'Não verão a terra da qual jurei a seus pais: não, nenhum dos que me irritaram a verá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 24, 'Porém meu servo Calebe, porquanto houve nele outro espírito, e cumpriu de ir após mim, eu o porei na terra onde entrou e sua descendência a receberá em herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 25, 'Agora bem, os amalequitas e os cananeus habitam no vale; voltai-vos amanhã, e parti-vos ao deserto, caminho do mar Vermelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 26, 'E o SENHOR falou a Moisés e a Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 27, 'Até quando ouvirei esta depravada multidão que murmura contra mim, as queixas dos filhos de Israel, que de mim se queixam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 28, 'Dize-lhes: Vivo eu, diz o SENHOR, que segundo falastes a meus ouvidos, assim farei eu convosco:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 29, 'Neste deserto cairão vossos corpos; todos vossos contados segundo toda vossa contagem, de vinte anos acima, os quais murmurastes contra mim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 30, 'Vós à verdade não entrareis na terra, pela qual levantei minha mão de fazer-vos habitar nela; exceto a Calebe filho de Jefoné, e a Josué filho de Num.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 31, 'Mas vossos meninos, dos quais dissestes que seriam por presa, eu os introduzirei, e eles conhecerão a terra que vós desprezastes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 32, 'E quanto a vós, vossos corpos cairão neste deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 33, 'E vossos filhos andarão pastoreando no deserto quarenta anos, e eles levarão vossas prostituições, até que vossos corpos sejam consumidos no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 34, 'Conforme o número dos dias, dos quarenta dias em que reconhecestes a terra, levareis vossas iniquidades quarenta anos, ano por cada dia; e conhecereis meu castigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 35, 'Eu sou o SENHOR falei; assim farei a toda esta multidão perversa que se juntou contra mim; neste deserto serão consumidos, e ali morrerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 36, 'E os homens que Moisés enviou para reconhecer a terra, e depois de voltarem, fizeram toda a congregação murmurar contra ele, trazendo um mau relato daquela terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 37, 'aqueles homens que haviam falado mal da terra, morreram de praga diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 38, 'Mas Josué filho de Num, e Calebe filho de Jefoné, restaram com vida dentre aqueles homens que haviam ido a reconhecer a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 39, 'E Moisés disse estas coisas a todos os filhos de Israel, e o povo ficou em muito luto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 40, 'E levantaram-se pela manhã, e subiram ao cume do monte, dizendo: Eis-nos aqui para subir ao lugar do qual falou o SENHOR; porque pecamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 41, 'E disse Moisés: Por que quebrantais o dito do SENHOR? Isto tampouco vos sucederá bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 42, 'Não subais, porque o SENHOR não está em meio de vós, não sejais feridos diante de vossos inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 43, 'Porque os amalequitas e os cananeus estão ali diante de vós, e caireis à espada: pois porquanto vos desviastes de seguir ao SENHOR, por isso não será o SENHOR convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 44, 'Todavia, se insistiram em subir por cima do monte: mas a arca da aliança do SENHOR, e Moisés, não se apartaram do meio do acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 14, 45, 'E desceram os amalequitas e os cananeus, que habitavam naquele monte, e os feriram e os derrotaram, perseguindo-os até Hormá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 1, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 2, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes entrado na terra de vossas habitações, que eu vos dou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 3, 'E fizerdes oferta queimada ao SENHOR, holocausto, ou sacrifício, por especial voto, ou de vossa vontade, ou para fazer em vossas solenidades cheiro suave ao SENHOR, de vacas ou de ovelhas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 4, 'Então o que oferecer sua oferta ao SENHOR, trará por oferta de cereais um décimo de um efa de boa farinha, amassada com a quarta parte de um him de azeite;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 5, 'E de veio para a libação oferecerás a quarta parte de um him, além do holocausto ou do sacrifício, por cada cordeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 6, 'E para cada carneiro farás oferta de cereais de dois décimos [de efa] de boa farinha, amassada com o terço de um him de azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 7, 'e de vinho para a libação oferecerás o terço de um him, em cheiro suave ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 8, 'E quando oferecerdes novilho em holocausto ou sacrifício, por especial voto, ou pacífico ao SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 9, 'Oferecerás com o novilho uma oferta de cereais de três décimos [de efa] de boa farinha, amassada com a metade de um him de azeite:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 10, 'E de vinho para a libação oferecerás a metade de um him, em oferta queimada de cheiro suave ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 11, 'Assim se fará com cada um boi, ou carneiro, ou cordeiro, o mesmo de ovelhas que de cabras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 12, 'Conforme o número assim fareis com cada um segundo o número deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 13, 'Todo natural fará estas coisas assim, para apresentar oferta queimada de cheiro suave ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 14, 'E quando habitar convosco estrangeiro, ou qualquer um que estiver entre vós nas vossas gerações, se apresentar uma oferta queimada de cheiro suave ao SENHOR, como vós fizerdes, assim fará ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 15, 'Um mesmo estatuto tereis, vós da congregação e o estrangeiro que convosco mora; estatuto que será perpétuo por vossas gerações: como vós, assim será o peregrino diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 16, 'Uma mesma lei e um mesmo regulamento tereis, vós e o peregrino que convosco mora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 17, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 18, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes entrado na terra à qual eu vos levo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 19, 'Será que quando começardes a comer o pão da terra, oferecereis oferta ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 20, 'Da primeira parte que amassardes, oferecereis um bolo como oferta; como a oferta da eira, assim o oferecereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 21, 'Das primícias de vossas massas dareis ao SENHOR oferta por vossas gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 22, 'E quando errardes, e não fizerdes todos estes mandamentos que o SENHOR disse a Moisés,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 23, 'Todas as coisas que o SENHOR vos mandou pela mão de Moisés, desde o dia que o SENHOR o mandou, e daí em diante por vossas gerações,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 24, 'Será que, se o pecado foi feito involuntariamente por ignorância da congregação, toda a congregação oferecerá um novilho por holocausto, em cheiro suave ao SENHOR, com sua oferta de cereais e sua libação, conforme a lei; e um bode macho por expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 25, 'E o sacerdote fará expiação por toda a congregação dos filhos de Israel; e lhes será perdoado, porque foi erro por ignorância; eles trarão sua oferta, oferta queimada ao SENHOR, e sua expiação diante do SENHOR, por causa do seu erro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 26, 'E será perdoado a toda a congregação dos filhos de Israel, e ao estrangeiro que peregrina entre eles, porque foi erro por ignorância de todo o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 27, 'E se uma pessoa pecar por ignorância, oferecerá uma cabra de um ano por expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 28, 'E o sacerdote fará expiação pela pessoa que houver pecado, quando pecar por ignorância diante do SENHOR, e a reconciliará, e lhe será perdoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 29, 'O natural entre os filhos de Israel, e o peregrino que habitar entre eles, uma mesma lei tereis para o que fizer algo por acidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 30, 'Mas a pessoa que fizer algo com mão soberba, tanto o natural como o estrangeiro, ao SENHOR blasfemou; e a tal pessoa será eliminada do meio de seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 31, 'Porquanto teve em pouco a palavra do SENHOR, e deu por nulo seu mandamento, inteiramente será eliminada a tal pessoa: sua iniquidade será sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 32, 'E estando os filhos de Israel no deserto, acharam um homem que recolhia lenha em dia de sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 33, 'E os que lhe acharam recolhendo lenha trouxeram-lhe a Moisés e a Arão, e a toda a congregação:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 34, 'E puseram-no no cárcere, porque não estava declarado que lhe haviam de fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 35, 'E o SENHOR disse a Moisés: Invariavelmente morra aquele homem; apedreje-o com pedras toda a congregação fora do acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 36, 'Então o tirou a congregação fora do acampamento, e apedrejaram-no com pedras, e morreu; como o SENHOR mandou a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 37, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 38, 'Fala aos filhos de Israel, e dize-lhes que se façam franjas) nos arremates de suas roupas, por suas gerações; e ponham em cada franja dos arremates um cordão de azul:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 39, 'E vos servirá de franja, para que quando o virdes, vos lembreis de todos os mandamentos do SENHOR, para praticá-los; e não olheis segundo vosso coração e vossos olhos, atrás dos quais prostituís:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 40, 'Para que vos lembreis, e façais todos meus mandamentos, e sejais santos a vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 15, 41, 'Eu sou o SENHOR vosso Deus, que vos tirei da terra do Egito, para ser vosso Deus: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 1, 'E Coré, filho de Izar, filho de Coate, filho de Levi; e Datã e Abirão, filhos de Eliabe; e Om, filho de Pelete, dos filhos de Rúben, tomaram gente,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 2, 'E levantaram-se contra Moisés com duzentos e cinquenta homens dos filhos de Israel, príncipes da congregação, dos do conselho, homens de renome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 3, 'E se juntaram contra Moisés e Arão, e lhes disseram: Basta-vos, porque toda a congregação, todos eles são santos, e em meio deles está o SENHOR: por que, pois, vos levantais vós sobre a congregação do SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 4, 'E quando o ouviu Moisés, lançou-se sobre seu rosto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 5, 'E falou a Coré e a todo o seu grupo, dizendo: Amanhã mostrará o SENHOR quem é seu, e ao santo o fará chegar a si; e ao que ele escolher, ele o achegará a si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 6, 'Fazei isto: tomai incensários, Coré e todo o seu grupo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 7, 'E ponde fogo neles, e ponde neles incenso diante do SENHOR amanhã; e será que o homem a quem o SENHOR escolher, aquele será o santo: basta-vos isto, filhos de Levi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 8, 'Disse mais Moisés a Coré: Ouvi agora, filhos de Levi:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 9, 'Vos é pouco que o Deus de Israel vos haja apartado da congregação de Israel, fazendo-vos achegar a si para que ministrasses no serviço do tabernáculo do SENHOR, e estivésseis diante da congregação para ministrar-lhes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 10, 'E que te fez aproximar a ti, e a todos os teus irmãos os filhos de Levi contigo; para que procureis também o sacerdócio?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 11, 'Portanto, tu e todo o teu grupo sois os que vos juntais contra o SENHOR: pois Arão, que é para que contra ele murmureis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 12, 'E enviou Moisés a chamar a Datã e Abirão, filhos de Eliabe; mas eles responderam: Não iremos lá:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 13, 'É pouco que nos tenhas feito vir de uma terra que destila leite e mel, para fazer-nos morrer no deserto, mas que também te faças senhor de nós autoritariamente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 14, 'Nem tampouco nos puseste tu em terra que flua leite e mel, nem nos deste propriedades de terras e vinhas: hás de arrancar os olhos destes homens? Não subiremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 15, 'Então Moisés se irou em grande maneira, e disse ao SENHOR: Não olhes a sua oferta: nem ainda um asno tomei deles, nem a nenhum deles fiz mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 16, 'Depois disse Moisés a Coré: Tu e todo o teu grupo, ponde-vos amanhã diante do SENHOR; tu, e eles, e Arão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 17, 'E tomai cada um seu incensário, e ponde incenso neles, e achegai diante do SENHOR cada um seu incensário: duzentos e cinquenta incensários: tu também, e Arão, cada um com seu incensário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 18, 'E tomaram cada um seu incensário, e puseram neles fogo, e lançaram neles incenso, e puseram-se à porta do tabernáculo do testemunho com Moisés e Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 19, 'Já Coré havia feito juntar contra eles toda a congregação à porta do tabernáculo do testemunho: então a glória do SENHOR apareceu a toda a congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 20, 'E o SENHOR falou a Moisés e a Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 21, 'Apartai-vos dentre esta congregação, e os consumirei em um momento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 22, 'E eles se lançaram sobre seus rostos, e disseram: Deus, Deus dos espíritos de toda carne, não é um homem o que pecou? E te irarás tu contra toda a congregação?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 23, 'Então o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 24, 'Fala à congregação, dizendo: Apartai-vos de em derredor da tenda de Coré, Datã, e Abirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 25, 'E Moisés se levantou, e foi a Datã e Abirão; e os anciãos de Israel foram atrás dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 26, 'E ele falou à congregação, dizendo: Apartai-vos agora das tendas destes ímpios homens, e não toqueis nenhuma coisa sua, porque não pereçais em todos os seus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 27, 'E apartaram-se das tendas de Coré, de Datã, e de Abirão em derredor: e Datã e Abirão saíram e puseram-se às portas de suas tendas, com suas mulheres, e seus filhos, e suas crianças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 28, 'E disse Moisés: Em isto conhecereis que o SENHOR me enviou para que fizesse todas estas coisas: que não de meu coração as fiz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 29, 'Se como morrem todos os homens morrerem estes, ou se forem eles visitados à maneira de todos os homens, o SENHOR não me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 30, 'Mas se o SENHOR fizer uma nova coisa, e a terra abrir sua boca, e os tragar com todas suas coisas, e descerem vivos ao Xeol, então conhecereis que estes homens irritaram ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 31, 'E aconteceu, que em acabando ele de falar todas estas palavras, rompeu-se a terra que estava debaixo deles:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 32, 'E abriu a terra sua boca, e tragou-os a eles, e a suas casas, e a todos os homens de Coré, e a todos os seus pertences.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 33, 'E eles, com tudo o que tinham, desceram vivos ao Xeol, a a terra os cobriu, e pereceram do meio da congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 34, 'E todo Israel, os que estavam em derredor deles, fugiram ao grito deles; porque diziam: Não nos trague também a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 35, 'E saiu fogo do SENHOR, e consumiu os duzentos e cinquenta homens que ofereciam o incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 36, 'Então o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 37, 'Dize a Eleazar, filho de Arão sacerdote, que tome os incensários do meio do incêndio, e derrame mais ali o fogo; porque são santificados:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 38, 'Os incensários destes pecadores contra suas almas: e farão deles placas estendidas para cobrir o altar: porquanto ofereceram com eles diante do SENHOR, são santificados; e serão por sinal aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 39, 'E o sacerdote Eleazar tomou os incensários de bronze com que os queimados haviam oferecido; e estenderam-nos para cobrir o altar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 40, 'Em memorial aos filhos de Israel que nenhum estranho que não seja da descendência de Arão, chegue a oferecer incenso diante do SENHOR, para que não seja como Coré, e como seu grupo; segundo se o disse o SENHOR por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 41, 'No dia seguinte toda a congregação dos filhos de Israel murmurou contra Moisés e Arão, dizendo: Vós haveis matado ao povo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 42, 'E aconteceu que, quando se juntou a congregação contra Moisés e Arão, olharam até o tabernáculo do testemunho, e eis que a nuvem o havia coberto, e apareceu a glória do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 43, 'E vieram Moisés e Arão diante do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 44, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 45, 'Apartai-vos do meio desta congregação, e os consumirei em um momento. E eles se lançaram sobre seus rostos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 46, 'E disse Moisés A Arão: Toma o incensário, e põe nele fogo do altar, e sobre ele põe incenso, e vai logo à congregação, e faze expiação por eles; porque o furor saiu de diante da face do SENHOR: a mortandade começou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 47, 'Então tomou Arão o incensário, como Moisés disse, e correu em meio da congregação: e eis que a mortandade havia começado no povo: e ele pôs incenso, e fez expiação pelo povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 48, 'E pôs-se entre os mortos e os vivos, e cessou a mortandade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 49, 'E os que morreram naquela mortandade foram catorze mil e setecentos, sem os mortos pelo negócio de Coré.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 16, 50, 'Depois se voltou Arão a Moisés à porta do tabernáculo do testemunho, quando a mortandade havia cessado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 2, 'Fala aos filhos de Israel, e toma deles uma vara por cada casa dos pais, de todos os príncipes deles, doze varas conforme as casas de seus pais; e escreverás o nome de cada um sobre sua vara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 3, 'E escreverás o nome de Arão sobre a vara de Levi; porque cada cabeça de família de seus pais terá uma vara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 4, 'E as porás no tabernáculo do testemunho diante do testemunho, onde eu me declararei a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 5, 'E será, que o homem que eu escolher, sua vara florescerá: e farei cessar de sobre mim as queixas dos filhos de Israel, com que murmuram contra vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 6, 'E Moisés falou aos filhos de Israel, e todos os príncipes deles lhe deram varas; cada príncipe pelas casas de seus pais uma vara, em todas doze varas; e a vara de Arão estava entre as varas deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 7, 'E Moisés pôs as varas diante do SENHOR no tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 8, 'E aconteceu que no dia seguinte veio Moisés ao tabernáculo do testemunho; e eis que a vara de Arão da casa de Levi havia brotado, e produzido flores, e lançado renovos, e produzido amêndoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 9, 'Então tirou Moisés todas as varas de diante do SENHOR a todos os filhos de Israel; e eles o viram, e tomaram cada um sua vara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 10, 'E o SENHOR disse a Moisés: Volta a vara de Arão diante do testemunho, para que se guarde por sinal aos filhos rebeldes; e farás cessar suas queixas de sobre mim, para que não morram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 11, 'E o fez Moisés: como lhe mandou o SENHOR, assim fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 12, 'Então os filhos de Israel falaram a Moisés, dizendo: Eis que nós somos mortos, perdidos somos, todos nós somos perdidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 17, 13, 'Qualquer um que se chegar, o que se aproximar ao tabernáculo do SENHOR morrerá: Acabaremos de perecer todos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 1, 'E o SENHOR disse a Arão: Tu e teus filhos, e a casa de teu pai contigo, levareis o pecado do santuário: e tu e teus filhos contigo levareis o pecado de vosso sacerdócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 2, 'E a teus irmãos também, a tribo de Levi, a tribo de teu pai, faze-os chegar a ti, e juntem-se contigo, e te servirão; e tu e teus filhos contigo servireis diante do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 3, 'E guardarão o que tu ordenares, e o cargo de todo o tabernáculo: mas não chegarão aos utensílios santos nem ao altar, para que não morram eles e vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 4, 'Eles se juntarão, pois, contigo, e terão o cargo do tabernáculo do testemunho em todo o serviço do tabernáculo; nenhum estranho se há de chegar a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 5, 'E tereis a guarda do santuário, e a guarda do altar, para que não seja mais a ira sobre os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 6, 'Porque eis que eu tomei os vossos irmãos, os levitas, dentre os filhos de Israel, são dados a vós como presente da parte do SENHOR, para que sirvam no ministério do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 7, 'Porém tu e teus filhos contigo guardareis vosso sacerdócio em todo negócio do altar, e do véu dentro, e ministrareis. Eu vos dei como presente o serviço de vosso sacerdócio; e o estranho que se aproximar morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 8, 'Disse mais o SENHOR a Arão: Eis que eu te dei também a guarda de minhas ofertas: todas as coisas consagradas dos filhos de Israel te dei por razão da unção, e a teus filhos, por estatuto perpétuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 9, 'Isto será teu da oferta das coisas santas separadas do fogo: toda oferta deles, toda oferta de alimentos deles, e toda expiação pelo pecado deles, que me restituirão, será coisa santíssima para ti e para os teus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 10, 'No santuário a comerás; todo homem comerá dela: coisa santa será para ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 11, 'Isto também será teu: a oferta elevada de suas doações, e todas as ofertas movidas dos filhos de Israel, dei a ti, e aos teus filhos, e às tuas filhas contigo, por estatuto perpétuo; todo o limpo na tua casa comerá delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 12, 'De azeite, e de mosto, e de trigo, tudo o mais escolhido, as primícias disso, que apresentarão ao SENHOR, a ti as dei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 13, 'As primícias de todas as coisas da terra deles, as quais trarão ao SENHOR, serão tuas: todo limpo em tua casa comerá delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 14, 'Todo o consagrado por voto em Israel será teu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 15, 'Todo o que abrir madre em toda carne que oferecerão ao SENHOR, tanto de homens como de animais, será teu: mas farás resgatar o primogênito do homem: também farás resgatar o primogênito de animal impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 16, 'E de um mês farás efetuar o resgate deles, conforme tua avaliação, por preço de cinco siclos, ao siclo do santuário, que é de vinte óbolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 17, 'Mas o primogênito de vaca, e o primogênito de ovelha, e o primogênito de cabra, não resgatarás; são santificados; o sangue deles espargirás sobre o altar, e queimarás a gordura deles, como oferta queimada em cheiro suave ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 18, 'E a carne deles será tua: como o peito da oferta movida e como a coxa direita, será tua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 19, 'Todas as ofertas elevadas das coisas santas, que os filhos de Israel oferecerem ao SENHOR, dei-as a ti, e a teus filhos e a tuas filhas contigo, por estatuto perpétuo: pacto de sal perpétuo é diante do SENHOR para ti e para tua descendência contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 20, 'E o SENHOR disse a Arão: Da terra deles não terás herança, nem entre eles terás parte: Eu sou tua parte e tua herança em meio dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 21, 'E eis que eu dei aos filhos de Levi todos os dízimos em Israel por herança, por seu ministério, porquanto eles servem no ministério do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 22, 'E não chegarão mais os filhos de Israel ao tabernáculo do testemunho, para que não levem pecado, pelo qual morram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 23, 'Mas os levitas farão o serviço do tabernáculo do testemunho, e eles levarão sua iniquidade: estatuto perpétuo por vossas gerações; e não possuirão herança entre os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 24, 'Porque aos levitas dei por herança os dízimos dos filhos de Israel, que oferecerão ao SENHOR em oferta; pelo qual lhes disse: Entre os filhos de Israel não possuirão herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 25, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 26, 'Assim falarás aos levitas, e lhes dirás: Quando receberdes dos filhos de Israel os dízimos que da parte deles vos dei por vossa herança, deles oferecereis em oferta movida ao SENHOR, o dízimo dos dízimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 27, 'E a vossa oferta vos será contada como o grão da eira, e como a plenitude da prensa de uvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 28, 'Assim também vós oferecereis uma oferta ao SENHOR de todos os vossos dízimos que receberdes dos filhos de Israel; e deles dareis a oferta do SENHOR ao sacerdote Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 29, 'De todas as vossas doações oferecereis toda oferta ao SENHOR; de todo o melhor delas oferecereis a porção que será consagrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 30, 'E lhes dirás: Quando oferecerdes o melhor delas, será contado aos levitas por fruto da eira, e como produto da prensa de uvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 31, 'E o comereis em qualquer lugar, vós e vossa família; pois é vossa remuneração por vosso ministério no tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 18, 32, 'E quando vós houverdes oferecido disso o melhor seu, não levareis por ele pecado: e não haveis de contaminar as coisas santas dos filhos de Israel, e não morrereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 1, 'E o SENHOR falou a Moisés e a Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 2, 'Esta é a ordenança da lei que o SENHOR prescreveu, dizendo: Dize aos filhos de Israel que te tragam uma novilha vermelha, sem defeito, que não tenha mancha, sobre a qual não se tenha posto jugo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 3, 'e a dareis ao sacerdote Eleazar. Ele a tirará fora do acampamento, e a fará degolar em sua presença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 4, 'E tomará Eleazar o sacerdote de seu sangue com seu dedo, e espargirá até a dianteira do tabernáculo do testemunho com o sangue dela sete vezes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 5, 'E fará queimar a vaca ante seus olhos: seu couro e sua carne e seu sangue, com seu excremento, fará queimar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 6, 'Logo tomará o sacerdote pau de cedro, e hissopo, e escarlata, e o lançará em meio do fogo em que arde a vaca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 7, 'O sacerdote lavará logo suas roupas, lavará também sua carne com água, e depois entrará no acampamento; e será impuro o sacerdote até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 8, 'Também o que a queimou, lavará suas roupas em água, também lavará em água sua carne, e será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 9, 'E um homem limpo recolherá as cinzas da vaca, e as porá fora do acampamento em lugar limpo, e as guardará a congregação dos filhos de Israel para a água de separação: é uma expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 10, 'E o que recolheu as cinzas da vaca, lavará suas roupas, e será impuro até à tarde: e será aos filhos de Israel, e ao estrangeiro que peregrina entre eles, por estatuto perpétuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 11, 'O que tocar morto de qualquer pessoa humana, sete dias será impuro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 12, 'Este se purificará ao terceiro dia com esta água, e ao sétimo dia será limpo; e se ao terceiro dia não se purificar, não será limpo ao sétimo dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 13, 'Qualquer um que tocar em morto, em pessoa de homem que estiver morto, e não se purificar, o tabernáculo do SENHOR contaminou; e aquela pessoa será eliminada de Israel: porquanto a água da separação não foi espargida sobre ele, impuro será; e seu impureza será sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 14, 'Esta é a lei para quando alguém morrer na tenda: qualquer um que entrar na tenda e todo o que estiver nela, será impuro sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 15, 'E todo vaso aberto, sobre o qual não houver tampa bem ajustada, sera impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 16, 'E qualquer um que tocar em morto à espada sobre a face do campo, ou em morto, ou em osso humano, ou em sepulcro, sete dias será impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 17, 'E para o impuro tomarão da cinza da queimada vaca da expiação, e lançarão sobre ela água viva em um vaso:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 18, 'E um homem limpo tomará hissopo. e o molhará na água, e espargirá sobre a tenda, e sobre todos os móveis, e sobre as pessoas que ali estiverem, e sobre aquele que houver tocado o osso, ou o matado, ou o cadáver, ou o sepulcro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 19, 'E o limpo espargirá sobre o impuro ao terceiro e ao sétimo dia: e quando o haverá purificado ao dia sétimo, ele lavará logo suas roupas, e a si mesmo se lavará com água, e será limpo à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 20, 'E o que for impuro, e não se purificar, a tal pessoa será eliminada dentre a congregação, porquanto contaminou o tabernáculo do SENHOR: não foi espargida sobre ele a água de separação, é impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 21, 'E lhes será por estatuto perpétuo: também o que espargir a água da separação lavará suas roupas; e o que tocar a água da separação, será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 19, 22, 'E todo o que o impuro tocar, será impuro: e a pessoa que o tocar, será impura até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 1, 'E chegaram os filhos de Israel, toda a congregação, ao deserto de Zim, no mês primeiro, e assentou o povo em Cades; e ali morreu Miriã, e foi ali sepultada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 2, 'E como não havia água para a congregação, juntaram-se contra Moisés e Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 3, 'E brigou o povo com Moisés, e falaram dizendo: Antes que nós tivéssemos morrido quando pereceram nossos irmãos diante do SENHOR!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 4, 'E por que fizeste vir a congregação do SENHOR a este deserto, para que morramos aqui nós e nossos animais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 5, 'E por que nos fizeste subir do Egito, para trazer-nos a este mal lugar? Não é lugar de sementeira, de figueiras, de vinhas, nem romãs: nem ainda de água para beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 6, 'E foram-se Moisés e Arão de diante da congregação à porta do tabernáculo do testemunho, e lançaram-se sobre seus rostos; e a glória do SENHOR apareceu sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 7, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 8, 'Toma a vara e reúne a congregação, tu e Arão teu irmão, e falai à rocha em olhos deles; e ela dará sua água, e lhes tirarás águas da rocha, e darás de beber à congregação, e a seus animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 9, 'Então Moisés tomou a vara de diante do SENHOR, como ele lhe mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 10, 'E juntaram Moisés e Arão a congregação diante da rocha, e disse-lhes: Ouvi agora, rebeldes: Faremos para vós sair águas desta rocha?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 11, 'Então levantou Moisés sua mão, e feriu a rocha com sua vara duas vezes: e saíram muitas águas, e bebeu a congregação, e seus animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 12, 'E o SENHOR disse a Moisés e a Arão: Porquanto não crestes em mim, para santificar-me aos olhos dos filhos de Israel, portanto, não poreis esta congregação na terra que lhes dei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 13, 'Estas são as águas da briga, pelas quais contenderam os filhos de Israel com o SENHOR, e ele se santificou neles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 14, 'E enviou Moisés embaixadores ao rei de Edom desde Cades: Assim diz Israel teu irmão: Tu soubeste todo o trabalho que nos veio:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 15, 'Como nossos pais desceram ao Egito, e estivemos no Egito longo tempo, e os egípcios nos maltrataram, e a nossos pais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 16, 'E clamamos ao SENHOR, o qual ouviu nossa voz, e enviou anjo, e tirou-nos do Egito; e eis que estamos em Cades, cidade ao extremo de teus confins:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 17, 'Rogamo-te que passemos por tua terra; não passaremos por lavoura, nem por vinha, nem beberemos água de poços: pelo caminho real iremos, sem apartar-nos à direita nem à esquerda, até que havemos passado teu termo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 18, 'E Edom lhe respondeu: Não passarás por minha terra, de outra maneira sairei contra ti armado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 19, 'E os filhos de Israel disseram: Pelo caminho seguido iremos; e se bebermos tuas águas eu e meus gados, darei o preço delas: certamente sem fazer outra coisa, passarei de seguida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 20, 'E ele respondeu: Não passarás. E saiu Edom contra ele com muito povo, e mão forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 21, 'Não quis, pois, Edom deixar passar a Israel por seu termo, e apartou-se Israel dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 22, 'E partidos de Cades os filhos de Israel, toda aquela congregação, vieram ao monte de Hor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 23, 'E o SENHOR falou a Moisés e Arão no monte de Hor, nos confins da terra de Edom, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 24, 'Arão será reunido a seus povos; pois não entrará na terra que eu dize aos filhos de Israel, porquanto fostes rebeldes a meu mandamento nas águas da briga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 25, 'Toma a Arão e a Eleazar seu filho, e faze-os subir ao monte de Hor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 26, 'E faze desnudar a Arão suas roupas, e viste delas a Eleazar seu filho; porque Arão será reunido a seus povos, e ali morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 27, 'E Moisés fez como o SENHOR lhe mandou: e subiram ao monte de Hor à vista de toda a congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 28, 'E Moisés fez desnudar a Arão de suas roupas e vestiu-as a Eleazar seu filho: e Arão morreu ali no cume do monte: e Moisés e Eleazar desceram do monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 20, 29, 'E vendo toda a congregação que Arão era morto, fizeram-lhe luto por trinta dias todas as famílias de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 1, 'E quando o cananeu, o rei de Arade, que habitava ao sul, ouviu falar que Israel vinha pelo caminho de Atarim, lutou contra Israel, e dele levou alguns como prisioneiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 2, 'Então Israel fez voto ao SENHOR, e disse: Se com efeito entregares a este povo em minha mão, eu destruirei suas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 3, 'E o SENHOR escutou a voz de Israel, e entregou aos cananeus, e destruiu-os a eles e a suas cidades; e chamou o nome daquele lugar Hormá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 4, 'E partiram do monte de Hor, caminho do mar Vermelho, para rodear a terra de Edom; e abateu-se o ânimo do povo pelo caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 5, 'E falou o povo contra Deus e Moisés: Por que nos fizeste subir do Egito para que morrêssemos neste deserto? que nem há pão, nem água, e nossa alma tem ódio deste pão tão miserável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 6, 'E o SENHOR enviou entre o povo serpentes ardentes, que mordiam ao povo: e morreu muito povo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 7, 'Então o povo veio a Moisés, e disseram: Pecado temos por haver falado contra o SENHOR, e contra ti: roga ao SENHOR que tire de nós estas serpentes. E Moisés orou pelo povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 8, 'E o SENHOR disse a Moisés: Faze-te uma serpente ardente, e põe-a sobre a haste: e será que qualquer um que for mordido e olhar a ela, viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 9, 'E Moisés fez uma serpente de bronze, e a pôs sobre a haste, e foi, que quando alguma serpente mordia a algum, olhava à serpente de bronze, e vivia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 10, 'E partiram os filhos de Israel, e assentaram acampamento em Obote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 11, 'E partidos de Obote, assentaram em Ijé-Abarim, no deserto que está diante de Moabe, ao oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 12, 'Partidos dali, assentaram no vale de Zerede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 13, 'De ali moveram, e assentaram da outra parte de Arnom, que está no deserto, e que sai do termo dos amorreus; porque Arnom é termo de Moabe, entre Moabe e os amorreus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 14, 'Por isso se diz no livro das batalhas do SENHOR: Vaebe em Sufa, e nos ribeiros de Arnom:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 15, 'E à corrente dos ribeiros que vai a parar em Ar, e descansa no termo de Moabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 16, 'E dali vieram a Beer: este é o poço do qual o SENHOR disse a Moisés: Junta ao povo, e lhes darei água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 17, 'Então cantou Israel esta canção: Sobe, ó poço; a ele cantai:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 18, 'Poço, o qual cavaram os senhores; Cavaram-no os príncipes do povo, E o legislador, com seus bordões. E do deserto [partiram] para Matana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 19, 'E de Mataná a Naaliel: e de Naaliel a Bamote:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 20, 'E de Bamote ao vale que está nos campos de Moabe, e ao cume de Pisga, que está voltado a Jesimom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 21, 'E enviou Israel embaixadores a Seom, rei dos amorreus, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 22, 'Deixa-me passar por tua terra: não nos desviaremos pelos campos, nem pelas vinhas; não beberemos as águas dos poços; pelo caminho real iremos, até que passemos os teus termos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 23, 'Mas Seom não deixou passar a Israel por seus termos: antes juntou Seom todo seu povo, e saiu contra Israel no deserto: e veio a Jaza, e lutou contra Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 24, 'Mas Israel o feriu a fio de espada, e tomou sua terra desde Arnom até Jaboque, até os filhos de Amom: porque o termo dos filhos de Amom era forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 25, 'E tomou Israel todas estas cidades: e habitou Israel em todas as cidades dos amorreus, em Hesbom e em todas suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 26, 'Porque Hesbom era a cidade de Seom, rei dos amorreus; o qual havia tido guerra antes com o rei de Moabe, e tomado de seu poder toda a sua terra até Arnom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 27, 'Portanto, dizem os proverbistas: Vinde a Hesbom, Edifique-se e repare-se a cidade de Seom:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 28, 'Que fogo saiu de Hesbom, E chama da cidade de Seom, E consumiu a Ar de Moabe, aos senhores dos altos de Arnom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 29, 'Ai de ti, Moabe! Pereceste, povo de Camos: Pôs seus filhos em fuga, E suas filhas em cativeiro, por Seom rei dos amorreus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 30, 'Mas devastamos o reino deles; pereceu Hesbom até Dibom, E destruímos até Nofá e Medeba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 31, 'Assim habitou Israel na terra dos amorreus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 32, 'E enviou Moisés a reconhecer a Jazer; e tomaram suas aldeias, e expulsaram aos amorreus que estavam ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 33, 'E voltaram, e subiram caminho de Basã. E Ogue, rei de Basã, ele e todo o seu povo, saíram contra eles, para lutar em Edrei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 34, 'Então o SENHOR disse a Moisés: Não tenhas medo dele, que em tua mão o dei, a o e a todo seu povo, e a sua terra; e farás dele como fizeste de Seom, rei dos amorreus, que habitava em Hesbom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 21, 35, 'E feriram a ele, e a seus filhos, e a toda sua gente, sem que lhe restasse um, e possuíram sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 1, 'Depois os filhos de Israel partiram, e se assentaram nos campos de Moabe, desta parte do Jordão de Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 2, 'E viu Balaque, filho de Zipor, tudo o que Israel havia feito aos amorreus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 3, 'E Moabe temeu muito por causa do povo que era muito; e angustiou-se Moabe por causa dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 4, 'E disse Moabe aos anciãos de Midiã: Agora lamberá esta gente todos nossos entornos, como lambe o boi a grama do campo. E Balaque, filho de Zipor, era então rei de Moabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 5, 'Portanto enviou mensageiros a Balaão filho de Beor, a Petor, que está junto ao rio na terra dos filhos de seu povo, para que o chamassem, dizendo: Um povo saiu do Egito, e eis que cobre a face da terra, e habita diante de mim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 6, 'Vem pois agora, te rogo, amaldiçoa para mim este povo, porque é mais forte que eu: talvez poderei eu feri-lo, e lançá-lo da terra: que eu sei que o que tu abençoares, será bendito, e o que tu amaldiçoares, será maldito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 7, 'E foram os anciãos de Moabe e os anciãos de Midiã, com o [pagamento pela] adivinhação em sua mão, e chegaram a Balaão, e lhe disseram as palavras de Balaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 8, 'E ele lhes disse: Repousai aqui esta noite, e eu vos referirei as palavras, como o SENHOR me falar. Assim os príncipes de Moabe se restaram com Balaão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 9, 'E veio Deus a Balaão, e disse-lhe: Que homens são estes que estão contigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 10, 'E Balaão respondeu a Deus: Balaque filho de Zipor, rei de Moabe, enviou a mim dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 11, 'Eis que este povo que saiu do Egito, cobre a face da terra: vem pois agora, e amaldiçoa-o para mim; talvez poderei lutar com ele, e expulsá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 12, 'Então disse Deus a Balaão: Não vás com eles, nem amaldiçoes ao povo; porque é bendito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 13, 'Assim Balaão se levantou pela manhã, e disse aos príncipes de Balaque: Voltai-vos à vossa terra, porque o SENHOR não me quer deixar ir convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 14, 'E os príncipes de Moabe se levantaram, e vieram a Balaque, e disseram: Balaão não quis vir conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 15, 'E voltou Balaque a enviar outra vez mais príncipes, e mais nobres que os outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 16, 'Os quais vieram a Balaão, e disseram-lhe: Assim diz Balaque, filho de Zipor: Rogo-te que não deixes de vir a mim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 17, 'Porque sem dúvida te honrarei muito, e farei tudo o que me disseres: vem pois agora, almaldiçoa para mim a este povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 18, 'E Balaão respondeu, e disse aos servos de Balaque: Ainda que Balaque me desse sua casa cheia de prata e ouro, não posso transgredir a palavra do SENHOR meu Deus, para fazer coisa pequena nem grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 19, 'Rogo-vos, portanto, agora, que repouseis aqui esta noite, para que eu saiba que me volta a dizer o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 20, 'E veio Deus a Balaão de noite, e disse-lhe: Se homens vierem a te chamar, levanta-te e vai com eles: porém farás o que eu te disser.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 21, 'Assim Balaão se levantou pela manhã, e preparou sua jumenta, e foi com os príncipes de Moabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 22, 'E o furor de Deus se acendeu porque ele ia; e o anjo do SENHOR se pôs no caminho por adversário seu. Ia, pois, ele montado sobre sua jumenta, e com ele dois servos seus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 23, 'E a jumenta viu o anjo do SENHOR, que estava no caminho com sua espada exposta em sua mão; então a jumenta desviou-se do caminho, e foi pelo campo. Em seguida, Balaão espancou a jumenta para fazê-la voltar ao caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 24, 'Mas o anjo do SENHOR se pôs em uma vereda de vinhas que tinha parede de uma parte e parede de outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 25, 'E quando a jumenta viu o anjo do SENHOR, apegou-se à parede, e apertou contra a parede o pé de Balaão: e ele voltou a espancá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 26, 'E o anjo do SENHOR passou mais ali, e pôs-se em um lugar estreito, onde não havia caminho para desviar-se nem à direita nem à esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 27, 'E vendo a jumenta ao anjo do SENHOR, lançou-se debaixo de Balaão: e irou-se Balaão, e feriu à jumenta com um bordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 28, 'Então o SENHOR abriu a boca da jumenta, a qual disse a Balaão: Que te fiz, que me feriste estas três vezes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 29, 'E Balaão respondeu à jumenta: Porque te zombaste de mim: bom seria se eu tivesse espada em minha mão, que agora te mataria!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 30, 'E a jumenta disse a Balaão: Não sou eu tua jumenta? Sobre mim montaste desde que tu me tens até hoje; costumei a fazê-lo assim contigo? E ele respondeu: Não.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 31, 'Então o SENHOR abriu os olhos a Balaão, e viu ao anjo do SENHOR que estava no caminho, e tinha sua espada nua em sua mão. E Balaão fez reverência, e inclinou-se sobre seu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 32, 'E o anjo do SENHOR lhe disse: Por que feriste tua jumenta estas três vezes? eis que eu saí para me opor a ti, porque teu caminho é perverso diante de mim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 33, 'A jumenta me viu, e afastou-se logo de diante de mim estas três vezes: e se de mim não se houvesse afastado, eu também agora mataria a ti, e a ela deixaria viva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 34, 'Então Balaão disse ao anjo do SENHOR: Pequei, que não sabia que tu te punhas diante de mim no caminho: mas agora, se te parece mal, eu me voltarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 35, 'E o anjo do SENHOR disse a Balaão: Vai com esses homens: porém a palavra que eu te disser, essa falarás. Assim Balaão foi com os príncipes de Balaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 36, 'E ouvindo Balaque que Balaão vinha, saiu a recebê-lo à cidade de Moabe, que está junto ao termo de Arnom, que é a extremidade das fronteiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 37, 'E Balaque disse a Balaão: Não enviei eu a ti a chamar-te? por que não vieste a mim? não posso eu te honrar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 38, 'E Balaão respondeu a Balaque: Eis que eu vim a ti: mas poderei agora falar alguma coisa? A palavra que Deus puser em minha boca, essa falarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 39, 'E foi Balaão com Balaque, e vieram à Quiriate-Huzote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 40, 'E Balaque fez matar bois e ovelhas, e enviou a Balaão, e aos príncipes que estavam com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 22, 41, 'E no dia seguinte Balaque tomou a Balaão, e o fez subir aos lugares altos de Baal, e desde ali viu a extremidade do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 1, 'E Balaão disse a Balaque: Edifica para mim aqui sete altares, e prepara-me aqui sete bezerros e sete carneiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 2, 'E Balaque fez como lhe disse Balaão: e ofereceram Balaque e Balaão um bezerro e um carneiro em cada altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 3, 'E Balaão disse a Balaque: Põe-te junto a teu holocausto, e eu irei: talvez o SENHOR me virá ao encontro, e qualquer um coisa que me mostrar, eu a contarei a ti. E assim se foi só.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 4, 'E veio Deus ao encontro de Balaão, e este lhe disse: Sete altares ordenei, e em cada altar ofereci um bezerro e um carneiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 5, 'E o SENHOR pôs palavra na boca de Balaão, e disse-lhe: Volta a Balaque, e hás de falar assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 6, 'E voltou a ele, e eis que estava ele junto a seu holocausto, ele e todos os príncipes de Moabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 7, 'E ele tomou sua parábola, e disse: De Arã me trouxe Balaque, rei de Moabe, dos montes do oriente: Vem, amaldiçoa para mim a Jacó; E vem, condena a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 8, 'Por que amaldiçoarei eu ao que Deus não amaldiçoou? E por que condenarei ao que o SENHOR não condenou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 9, 'Porque do cume das penhas o verei, E desde as colinas o olharei: Eis aqui um povo que habitará confiante, e não será contado entre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 10, 'Quem contará o pó de Jacó, Ou o número da quarta parte de Israel? Morra minha pessoa da morte dos corretos, E meu fim seja como o seu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 11, 'Então Balaque disse a Balaão: Que me fizeste? Tomei-te para que amaldiçoes a meus inimigos, e eis que proferiste bênçãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 12, 'E ele respondeu, e disse: Não observarei eu o que o SENHOR puser em minha boca para dizê-lo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 13, 'E disse Balaque: Rogo-te que venhas comigo a outro lugar desde o qual o vejas; sua extremidade somente verás, que não o verás todo; e desde ali me o amaldiçoarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 14, 'E levou-o ao campo de Zofim, ao cume de Pisga, e edificou sete altares, e ofereceu um bezerro e um carneiro em cada altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 15, 'Então ele disse a Balaque: Põe-te aqui junto a teu holocausto, e eu irei a encontrar a Deus ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 16, 'E o SENHOR saiu ao encontro de Balaão, e pôs palavra em sua boca, e disse-lhe: Volta a Balaque, e assim dirás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 17, 'E veio a ele, e eis que ele estava junto a seu holocausto, e com ele os príncipes de Moabe: e disse-lhe Balaque: Que disse o SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 18, 'Então ele tomou sua parábola, e disse: Balaque, levanta-te e ouve; Escuta minhas palavras, filho de Zipor:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 19, 'Deus não é homem, para que minta; nem filho de homem para que se arrependa: ele disse, e não fará?; Falou, e não o executará?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 20, 'Eis que, eu tomei bênção: E ele abençoou, e não poderei revogá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 21, 'Não notou iniquidade em Jacó, nem viu perversidade em Israel: o SENHOR seu Deus é com ele, E júbilo de rei nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 22, 'Deus os tirou do Egito; Tem forças como de boi selvagem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 23, 'Porque em Jacó não há agouro, nem adivinhação em Israel: Como agora, será dito de Jacó e de Israel: O que fez Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 24, 'Eis que o povo, que como leão se levantará, E como leão se erguerá: Não se deitará até que coma a presa, E beba o sangue dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 25, 'Então Balaque disse a Balaão: Já que não o amaldiçoas, nem tampouco o abençoes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 26, 'E Balaão respondeu, e disse a Balaque: Não te disse que tudo o que o SENHOR me disser, aquilo tenho de fazer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 27, 'E disse Balaque a Balaão: Rogo-te que venhas, te levarei a outro lugar; porventura comparecerá bem a Deus que desde ali me o amaldiçoes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 28, 'E Balaque levou a Balaão ao cume de Peor, que está voltado até Jesimom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 29, 'Então Balaão disse a Balaque: Edifica para mim aqui sete altares, e prepara-me aqui sete bezerros e sete carneiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 23, 30, 'E Balaque fez como Balaão lhe disse; e ofereceu um bezerro e um carneiro em cada altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 1, 'E quando viu Balaão que parecia bem ao SENHOR que o abençoasse a Israel, não foi, como a primeira e segunda vez, a encontro de agouros, mas sim que pôs seu rosto até o deserto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 2, 'E levantando seus olhos, viu a Israel alojado por suas tribos; e o espírito de Deus veio sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 3, 'Então tomou sua parábola, e disse: Disse Balaão filho de Beor, E disse o homem de olhos abertos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 4, 'Disse o que ouviu os ditos de Deus, O que viu a visão do Todo-Poderoso; caído, mas abertos os olhos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 5, 'Quão belas são tuas tendas, ó Jacó, Tuas habitações, ó Israel!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 6, 'Como ribeiros estão estendidas, Como jardins junto ao rio, Como aloés plantados pelo SENHOR, Como cedros junto às águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 7, 'De suas mãos destilarão águas, E sua descendência será em muitas águas: E se levantará seu rei mais que Agague, E seu reino será exaltado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 8, 'Deus o tirou do Egito; Tem forças como de boi selvagem: Comerá às nações suas inimigas, E esmiuçará seus ossos, E perfurará com suas flechas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 9, 'Se encurvará para deitar-se como leão, E como leoa; quem o despertará? Benditos os que te abençoarem, E malditos os que te amaldiçoarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 10, 'Então se acendeu a ira de Balaque contra Balaão, e batendo suas palmas lhe disse: Para amaldiçoar a meus inimigos te chamei, e eis que os abençoaste insistentemente já três vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 11, 'Foge-te, portanto, agora a teu lugar: eu disse que te honraria, mas eis que o SENHOR te privou de honra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 12, 'E Balaão lhe respondeu: Não o declarei eu também a teus mensageiros que me enviaste, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 13, 'Se Balaque me desse sua casa cheia de prata e ouro, eu não poderei transgredir o dito do SENHOR para fazer coisa boa nem má de minha vontade; mas o que o SENHOR falar, isso direi eu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 14, 'Eis que eu me vou agora a meu povo: portanto, vem, te indicarei o que este povo há de fazer a teu povo nos últimos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 15, 'E tomou sua parábola, e disse: Disse Balaão filho de Beor, Disse o homem de olhos abertos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 16, 'Disse o que ouviu os ditos do SENHOR, E o que sabe o conhecimento do Altíssimo, o que viu a visão do Todo-Poderoso; caído, mas abertos os olhos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 17, 'Verei, mas não agora: O olharei, mas não de perto: Sairá estrela de Jacó, E se levantará cetro de Israel, E ferirá os cantos de Moabe, E destruirá a todos os filhos de Sete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 18, 'E será tomada Edom, Será também tomada Seir por seus inimigos, E Israel se portará corajosamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 19, 'E o de Jacó será dominador, E destruirá da cidade o que restar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 20, 'E vendo a Amaleque, tomou sua parábola, e disse: Amaleque, cabeça de nações; Mas seu fim perecerá para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 21, 'E vendo aos queneus, tomou sua parábola, e disse: Forte é tua habitação, Põe na rocha tua ninho:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 22, 'Que os queneus serão expulsos, Quando Assur te levará cativo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 23, 'Todavia tomou sua parábola, e disse: Ai! quem viverá quando fizer Deus estas coisas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 24, 'E virão navios da costa de Quitim, E afligirão a Assur, afligirão também a Éber: Mas ele também perecerá para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 24, 25, 'Então se levantou Balaão, e se foi, e voltou-se a seu lugar: e também Balaque se foi por seu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 1, 'E repousou Israel em Sitim, e o povo começou a se prostituir com as filhas de Moabe:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 2, 'As quais chamaram ao povo aos sacrifícios de seus deuses: e o povo comeu, e inclinou-se a seus deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 3, 'E achegou-se o povo a Baal-Peor; e o furor do SENHOR se acendeu contra Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 4, 'E o SENHOR disse a Moisés: Toma todos os príncipes do povo, e enforca-os ao SENHOR diante do sol; e a ira do furor do SENHOR se apartará de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 5, 'Então Moisés disse aos juízes de Israel: Matai cada um àqueles dos seus que se recolheram a Baal-Peor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 6, 'E eis que um homem dos filhos de Israel veio e trouxe uma midianita a seus irmãos, à vista de Moisés e de toda a congregação dos filhos de Israel, chorando eles à porta do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 7, 'E viu-o Fineias, filho de Eleazar, filho de Arão o sacerdote, e levantou-se do meio da congregação, e tomou uma lança em sua mão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 8, 'E foi atrás do homem de Israel à tenda, e perfurou com a lança a ambos, ao homem de Israel, e à mulher por seu ventre. E cessou a mortandade dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 9, 'E morreram daquela mortandade vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 10, 'Então o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 11, 'Fineias, filho de Eleazar, filho de Arão o sacerdote, fez afastar meu furor dos filhos de Israel, levado de zelo entre eles: pelo qual eu não consumi em meu zelo aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 12, 'Portanto dize lhes: Eis que eu estabeleço meu pacto de paz com ele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 13, 'E terá ele, e sua descendência depois dele, o pacto do sacerdócio perpétuo; porquanto teve zelo por seu Deus, e fez expiação pelos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 14, 'E o nome do homem morto, que foi morto com a midianita, era Zinri filho de Salu, chefe de uma família da tribo de Simeão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 15, 'E o nome da mulher midianita morta, era Cosbi, filha de Zur, príncipe de povos, pai de família em Midiã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 16, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 17, 'Sereis hostis aos midianitas, e os ferireis:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 25, 18, 'Porquanto eles vos afligiram com suas astúcias, com que vos enganaram no negócio de Peor, e no negócio de Cosbi, filha do príncipe de Midiã, sua irmã, a qual foi morta no dia da mortandade por causa de Peor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 1, 'E aconteceu depois da mortandade, que o SENHOR falou a Moisés, e a Eleazar filho do sacerdote Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 2, 'Tomai a soma de toda a congregação dos filhos de Israel, de vinte anos acima, pelas casas de seus pais, todos os que possam sair à guerra em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 3, 'E Moisés e Eleazar o sacerdote falaram com eles nos campos de Moabe, junto ao Jordão de Jericó, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 4, 'Contareis o povo de vinte anos acima, como mandou o SENHOR a Moisés e aos filhos de Israel, que haviam saído da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 5, 'Rúben primogênito de Israel: os filhos de Rúben: Enoque, do qual era a família dos enoquitas; de Palu, a família dos paluítas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 6, 'De Hezrom, a família dos hezronitas; de Carmi, a família dos carmitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 7, 'Estas são as famílias dos rubenitas: e seus contados foram quarenta e três mil setecentos e trinta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 8, 'E os filhos de Palu: Eliabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 9, 'E os filhos de Eliabe: Nemuel, e Datã, e Abirão. Estes Datã e Abirão foram os do conselho da congregação, que fizeram o motim contra Moisés e Arão com a companhia de Coré, quando se amotinaram contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 10, 'Que a terra abriu sua boca e tragou a eles e a Coré, quando aquela companhia morreu, quando consumiu o fogo duzentos e cinquenta homens, os quais foram por sinal.')
